def auditar(func):
    def wrapper(*args, **kwargs):
        print("Antes de ejecutar")
        res = func(*args, **kwargs)
        print("Despues de ejecutar")
        return res
    return wrapper

@auditar
def sumar(a, b):
    return a + b

print("Resultado:", sumar(10, 5))

