from functools import wraps

def auditable(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapper

@auditable
def login_usuario():
    """Autentica las credenciales del usuario."""
    return True

print("Nombre:", login_usuario.__name__)
print("Doc:", login_usuario.__doc__)

