from functools import wraps

def con_prefijo(tag):
    def decorador(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            print(f"[{tag}] Iniciando...")
            return func(*args, **kwargs)
        return wrapper
    return decorador

@con_prefijo("SEGURIDAD")
def borrar_cuenta():
    return "Cuenta eliminada"

print(borrar_cuenta())

